package test;

// Mock minimal interface to avoid complex Eclipse dependencies in example.
// In a real scenario, org.eclipse.jdt.core.IJavaElement would be on the classpath.
interface IJavaElement {
    int TYPE = 1; // Simulate IJavaElement.TYPE
    String getElementName();
    int getElementType();
}

class MyJavaElement implements IJavaElement {
    private String name;
    private int type;

    public MyJavaElement(String name, int type) { this.name = name; this.type = type; }
    @Override public String getElementName() { return name; }
    @Override public int getElementType() { return type; }
}

public class MyChecker {
    public boolean checkCondition(MyJavaElement inputElement, MyJavaElement typeElement) {
        int inputType = inputElement.getElementType();
        if (inputType == IJavaElement.TYPE && inputElement.getElementName().equals(typeElement.getElementName())) {
            return true;
        }
        return false;
    }
}

